``` {.python .cell-code}
def parent_verdict(parent):
    """parent[v] in 0..n-1, or -1 for a root. Vertices 0..n-1."""
    n = len(parent)
    roots = 0
    for v, p in enumerate(parent):
        if p == -1:
            roots += 1
        elif not (0 <= p < n) or p == v:
            return "bad parent"
    if roots == 0:
        return "no root"
    if roots > 1:
        return "several roots (a forest)"
    seen = [False] * n
    for start in range(n):
        v = start
        guard = 0
        while parent[v] != -1 and not seen[v] and guard <= n:
            v = parent[v]
            guard += 1
        if parent[v] != -1 and not seen[v]:
            return "a cycle: some vertices never reach the root"
        v = start
        while not seen[v]:
            seen[v] = True
            if parent[v] == -1:
                break
            v = parent[v]
    return "a tree" if all(seen) else "a cycle: some vertices never reach the root"


assert parent_verdict([-1, 0, 0, 0, 1, 1, 2, 4, 4, 6]) == "a tree"
assert parent_verdict([-1, 0, 3, 2]) == "a cycle: some vertices never reach the root"
assert parent_verdict([-1, -1, 0, 1]) == "several roots (a forest)"
assert parent_verdict([1, 0]) == "no root"
assert parent_verdict([2, -1, 1, 1, 3]) == "a tree"
```
