##### Python

::: {#684ad5f9 .cell execution_count=45}
``` {.python .cell-code}
def binary_tree_paths(root):
    out, path = [], []

    def walk(u):
        path.append(str(u.val))
        if u.left is None and u.right is None:
            out.append("->".join(path))
        if u.left:
            walk(u.left)
        if u.right:
            walk(u.right)
        path.pop()

    if root:
        walk(root)
    return out
```
