``` {.python .cell-code}
def ehab_at_hub(n, edges):
    deg = [0] * (n + 1)
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
    hub = next((x for x in range(n, 0, -1) if deg[x] >= 3), None)
    label = [-1] * (n - 1)
    nxt = 0
    if hub is not None:
        for i, (u, v) in enumerate(edges):
            if nxt >= 3:
                break
            if u == hub or v == hub:
                label[i] = nxt
                nxt += 1
    for i in range(n - 1):
        if label[i] == -1:
            label[i] = nxt
            nxt += 1
    return label
```
