def ehab_at_leaves(n, edges):
    deg = [0] * (n + 1)
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
    leaves = sum(1 for x in range(1, n + 1) if deg[x] == 1)
    label = [-1] * (n - 1)
    nxt = 0
    if leaves >= 3:
        for i, (u, v) in enumerate(edges):
            if nxt >= 3:
                break
            if deg[u] == 1 or deg[v] == 1:
                label[i] = nxt
                nxt += 1
    for i in range(n - 1):
        if label[i] == -1:
            label[i] = nxt
            nxt += 1
    return label


def largest_mex(n, edges, label):
    """Largest path MEX. Labels are small on the trees this checks."""
    adj = [[] for _ in range(n + 1)]
    for i, (u, v) in enumerate(edges):
        adj[u].append((v, label[i]))
        adj[v].append((u, label[i]))
    best = 0
    for s in range(1, n + 1):
        st = [(s, -1, 0)]
        while st:
            u, parent, mask = st.pop()
            for v, lab in adj[u]:
                if v == parent:
                    continue
                nm = mask | (1 << lab)
                mex = 0
                while nm & (1 << mex):
                    mex += 1
                best = max(best, mex)
                st.append((v, u, nm))
    return best


