def arboris(n, edges):
    if n == 2:
        return 0
    deg = [0] * (n + 1)
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
    leaves = sum(deg[x] == 1 for x in range(1, n + 1))
    leaf_nb = [0] * (n + 1)
    for u, v in edges:
        if deg[u] == 1:
            leaf_nb[v] += 1
        if deg[v] == 1:
            leaf_nb[u] += 1
    return leaves - max(leaf_nb)


