##### Python

::: {#ef2ea509 .cell execution_count=75}
``` {.python .cell-code}
def transit(n, edges, k, queries):
    adj = [[] for _ in range(n + 1)]
    for a, b, c in edges:
        adj[a].append((b, c))
        adj[b].append((a, c))
    dist = [-1] * (n + 1)
    dist[k] = 0
    order = [k]
    h = 0
    while h < len(order):
        u = order[h]
        h += 1
        for v, w in adj[u]:
            if dist[v] < 0:
                dist[v] = dist[u] + w
                order.append(v)
    return [dist[x] + dist[y] for x, y in queries]
```
:::


##### C++

```cpp
vector<long long> transit(int n, const vector<tuple<int, int, long long>>& edges,
                          int k, const vector<pair<int, int>>& queries) {
    vector<vector<pair<int, long long>>> adj(n + 1);
    for (auto [a, b, c] : edges) {
        adj[a].push_back({b, c});
        adj[b].push_back({a, c});
    }
    vector<long long> dist(n + 1, -1);
    dist[k] = 0;
    queue<int> q;
    q.push(k);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (auto [v, w] : adj[u])
            if (dist[v] < 0) {
                dist[v] = dist[u] + w;
                q.push(v);
            }
    }
    vector<long long> ans;
    for (auto [x, y] : queries) ans.push_back(dist[x] + dist[y]);
    return ans;
}
```

