##### Python

::: {#534f575f .cell execution_count=81}
``` {.python .cell-code}
def amount_of_time(root, start):
    parent = {root: None}
    source = None
    stack = [root]
    while stack:
        u = stack.pop()
        if u.val == start:
            source = u
        for c in (u.left, u.right):
            if c is not None:
                parent[c] = u
                stack.append(c)
    dist = {source: 0}
    q = deque([source])
    best = 0
    while q:
        u = q.popleft()
        best = max(best, dist[u])
        for v in (u.left, u.right, parent[u]):
            if v is not None and v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)
    return best
```
:::


##### C++

```cpp
int amountOfTime(TreeNode* root, int start) {
    unordered_map<TreeNode*, TreeNode*> parent;
    parent[root] = nullptr;
    TreeNode* source = nullptr;
    vector<TreeNode*> st = {root};
    while (!st.empty()) {
        auto u = st.back();
        st.pop_back();
        if (u->val == start) source = u;
        for (auto c : {u->left, u->right})
            if (c) { parent[c] = u; st.push_back(c); }
    }
    unordered_map<TreeNode*, int> dist;
    dist[source] = 0;
    queue<TreeNode*> q;
    q.push(source);
    int best = 0;
    while (!q.empty()) {
        auto u = q.front();
        q.pop();
        best = max(best, dist[u]);
        for (auto v : {u->left, u->right, parent[u]})
            if (v && !dist.count(v)) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
    }
    return best;
}
```

